package edu.klh.soa.auth; import edu.klh.soa.security.JwtUtil;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/auth") public class AuthController {record Login(String username,String password){} @PostMapping("/login") public Map<String,Object> login(@RequestBody Login l){Map<String,String> users=Map.of("recall.officer","demo123","shelf.clerk","demo123","admin","admin123");if(l==null||!Objects.equals(users.get(l.username()),l.password()))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.UNAUTHORIZED,"invalid credentials");String role=l.username().equals("shelf.clerk")?"SHELF_CLERK":l.username().equals("admin")?"ADMIN":"RECALL_OFFICER";return Map.of("token",JwtUtil.issue(l.username(),role),"tokenType","Bearer","expiresInSeconds",3600,"role",role);} @GetMapping("/health") public Map<String,String> health(){return Map.of("status","UP");}}
